type Localized = { en: string; mr?: string };
type ContentItem = {
  _id?: string; slug?: string; title?: Localized; name?: Localized; description?: Localized;
  excerpt?: Localized; image?: string; date?: string; publishDate?: string; eventType?: string;
  featuredImage?: string; shortDescription?: Localized; content?: Localized;
  status?: string; category?: Localized | string; location?: Localized; capacity?: number;
  file?: string; fileUrl?: string; value?: string | number; suffix?: string; label?: Localized;
};

type SiteSettings = {
  siteName?: Localized; siteEmail?: string; sitePhone?: string; siteAddress?: Localized;
  logoUrl?: string; footerIntro?: Localized; facebook?: string; instagram?: string;
  linkedin?: string; youtube?: string; twitter?: string;
  headerNavigation?: Array<{ label: Localized; url: string; order: number; isActive: boolean }>;
  footerNavigation?: Array<{ label: Localized; url: string; order: number; isActive: boolean }>;
  newsletterSettings?: { enabled?: boolean; consentText?: Localized };
  mediaCarouselInterval?: number;
  homepageSections?: Array<{ key: string; heading: string; description?: string; ctaLabel?: string; ctaUrl?: string; enabled: boolean; order: number }>;
};

type MemberBusiness = { _id:string; companyName:string; slug:string; industry:string; city:string; logoUrl?:string; description:string; website?:string; enquiryEnabled:boolean; featured:boolean };
type BusinessOpportunity = { _id:string; title:string; category:string; industry:string; city:string; description:string; createdAt:string; closingDate?:string; featured:boolean; imageUrl?:string; detailUrl?:string; displayOrder?:number };
type MemberStory = { _id:string; name?:Localized; company?:string; designation?:Localized; content?:Localized; photo?:string; isActive:boolean };
type VenueItem = { _id:string; slug:string; name:Localized; description:Localized; capacity:number; idealUsage?:Localized; images:string[]; isActive:boolean };

